class Solution {
public:
    int maximumLength(string s) {
        int n = s.size();
        int ans = -1;
        vector<array<int,3>> top(26, {0,0,0}); // top[0] >= top[1] >= top[2]
        int run = 0;
        char prev = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == prev) run++;
            else { run = 1; prev = s[i]; }
            int c = s[i] - 'a';
            if (run > top[c][0]) {
                top[c][2] = top[c][1];
                top[c][1] = top[c][0];
                top[c][0] = run;
            } else if (run > top[c][1]) {
                top[c][2] = top[c][1];
                top[c][1] = run;
            } else if (run > top[c][2]) {
                top[c][2] = run;
            }
        }
        for (int c = 0; c < 26; c++) {
            if (top[c][2] > 0) ans = max(ans, top[c][2]);
        }
        return ans;
    }
};
